    if ((m = /^(<>|<=|>=)/.exec(s.slice(i)))) { toks.push({ t: 'op', v: m[0] }); i += 2; continue }
    if ('^*/+-=<>(),:'.includes(c)) { toks.push({ t: 'op', v: c }); i++; continue }
    return null
  }
  return toks
}

class Fail extends Error {}

function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => toks[p] && toks[p].t === 'op' && toks[p].v === v
  const fail = () => { throw new Fail() }
  function cmp() {
    let l = add()
    while (peek() && peek().t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(peek().v)) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { n: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { n: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    const t = peek()
    if (!t) fail()
    if (t.t === 'num') { p++; return { n: 'num', v: t.v } }
    if (t.t === 'op' && t.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) fail()
      p++
      return e
    }
    if (t.t === 'word') {
      p++
      if (isOp('(')) {
        p++
        const argv = []
        if (isOp(')')) { p++ } else {
          for (;;) {
            argv.push(cmp())
            if (isOp(',')) { p++; continue }
            if (isOp(')')) { p++; break }
            fail()
          }
        }
        return { n: 'call', name: t.v, args: argv }
      }
      if (isOp(':')) {
        p++
        const t2 = peek()
        if (!t2 || t2.t !== 'word') fail()
        p++
        return { n: 'range', a: t.v, b: t2.v }
      }
      if (t.v === 'TRUE') return { n: 'bool', v: true }
      if (t.v === 'FALSE') return { n: 'bool', v: false }
      return { n: 'ref', name: t.v }
    }
    fail()
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch (e) {
    if (e instanceof Fail) return null
    throw e
  }
}

// ---------- evaluation
const parsed = new Map()
for (const c of sorted) {
  if (c.content[0] === '=') parsed.set(c.name, parseFormula(c.content.slice(1)))
}

function rangeCells(a, b) {
  const A = parseAddr(a), B = parseAddr(b)
  if (!A || !B) return null
  const out = []
  for (let c = Math.min(A.col, B.col); c <= Math.max(A.col, B.col); c++)
    for (let r = Math.min(A.row, B.row); r <= Math.max(A.row, B.row); r++) out.push(addrName(c, r))
  return out
}

const memo = new Map()
const visiting = new Set()
function cellValue(name) {
  if (memo.has(name)) return memo.get(name)
  const c = cells.get(name)
  if (!c) return ZERO
  if (visiting.has(name)) return err('#CYCLE!')
  visiting.add(name)
  let v
  const s = c.content
  if (s[0] === '=') {
    const ast = parsed.get(name)
    v = ast ? evalNode(ast) : err('#ERR!')
    if (v.k === 'r') v = err('#ERR!')
  } else if (s === '') v = ZERO
  else if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) v = num(parseFloat(s))
  else if (ERRS.includes(s)) v = err(s)
  else v = { k: 's', v: s }
  visiting.delete(name)
  memo.set(name, v)
  return v
}

function fin(n) { return Number.isFinite(n) ? num(n) : err('#DIV/0!') }
function toNum(v) {
  if (v.k === 'n') return v
  if (v.k === 'b') return num(v.v ? 1 : 0)
  return err('#VALUE!')
}
const rank = { n: 0, s: 1, b: 2 }
function compare(a, b) {
  if (a.k !== b.k) return rank[a.k] - rank[b.k]
  if (a.k === 's') {
    const x = [...a.v], y = [...b.v]
    for (let i = 0; i < Math.min(x.length, y.length); i++) {
      const d = x[i].codePointAt(0) - y[i].codePointAt(0)
      if (d) return d
    }
    return x.length - y.length
  }
  const x = a.k === 'b' ? +a.v : a.v, y = b.k === 'b' ? +b.v : b.v
  return x < y ? -1 : x > y ? 1 : 0
}

function evalNode(n) {
  switch (n.n) {
    case 'num': return num(n.v)
    case 'bool': return { k: 'b', v: n.v }
    case 'ref': {
      const a = parseAddr(n.name)
      return a ? cellValue(a.name) : err('#REF!')
    }
    case 'range': return err('#ERR!')
    case 'un': {
      const v = evalNode(n.e)
      if (v.k === 'e') return v
      const x = toNum(v)
      if (x.k === 'e') return x
      return num(n.op === '-' ? -x.v : x.v)
    }
    case 'bin': {
      const l = evalNode(n.l), r = evalNode(n.r)
      if (l.k === 'e') return l
      if (r.k === 'e') return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        const c = compare(l, r)
        const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
        return { k: 'b', v: res }
      }
      const a = toNum(l)
      if (a.k === 'e') return a
      const b = toNum(r)
      if (b.k === 'e') return b
      switch (n.op) {
        case '+': return fin(a.v + b.v)
        case '-': return fin(a.v - b.v)
        case '*': return fin(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
        case '^': return fin(Math.pow(a.v, b.v))
      }
      return err('#ERR!')
    }
    case 'call': return evalCall(n)
  }
  return err('#ERR!')
}

function evalCall(n) {
  const name = n.name, args = n.args
  const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
  if (!known.includes(name)) return err('#NAME?')
  if (name === 'IF') {
    if (args.length !== 3) return err('#ERR!')
    const c = args[0].n === 'range' ? err('#ERR!') : evalNode(args[0])
    if (c.k === 'e') return c
    let t
    if (c.k === 'b') t = c.v
    else if (c.k === 'n') t = c.v !== 0
    else return err('#VALUE!')
    const br = args[t ? 1 : 2]
    return br.n === 'range' ? err('#ERR!') : evalNode(br)
  }
  if (name === 'ABS') {
    if (args.length !== 1) return err('#ERR!')
    if (args[0].n === 'range') return err('#ERR!')
    const v = evalNode(args[0])
    if (v.k === 'e') return v
    const x = toNum(v)
    return x.k === 'e' ? x : num(Math.abs(x.v))
  }
  if (args.length < 1) return err('#ERR!')
  const vals = []
  for (const a of args) {
    if (a.n === 'range') {
      const cs = rangeCells(a.a, a.b)
      if (!cs) vals.push(err('#REF!'))
      else for (const c of cs) vals.push(cellValue(c))
    } else vals.push(evalNode(a))
  }
  const e = vals.find((v) => v.k === 'e')
  if (e) return e
  if (name === 'COUNT') return num(vals.filter((v) => v.k === 'n').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.k === 'e') return x
    nums.push(x.v)
  }
  switch (name) {
    case 'SUM': return fin(nums.reduce((a, b) => a + b, 0))
    case 'MIN': return fin(Math.min(...nums))
    case 'MAX': return fin(Math.max(...nums))
    case 'AVG': return fin(nums.reduce((a, b) => a + b, 0) / nums.length)
  }
  return err('#ERR!')
}

function fmt(v) {
  switch (v.k) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

function collect(n, set) {
  switch (n.n) {
    case 'ref': { const a = parseAddr(n.name); if (a) set.set(a.name, a); break }
    case 'range': {
      const cs = rangeCells(n.a, n.b)
      if (cs) for (const c of cs) set.set(c, parseAddr(c))
      break
    }
    case 'un': collect(n.e, set); break
    case 'bin': collect(n.l, set); collect(n.r, set); break
    case 'call': for (const a of n.args) collect(a, set); break
  }
}

const out = []
for (const c of sorted) {
  if (mode === 'values') out.push(`${c.name}=${fmt(cellValue(c.name))}`)
  else {
    const set = new Map()
    const ast = parsed.get(c.name)
    if (ast) collect(ast, set)
    const list = [...set.values()].sort((x, y) => x.col - y.col || x.row - y.row)
    out.push(`${c.name}:` + list.map((a) => ' ' + a.name).join(''))
  }
}
process.stdout.write(out.length ? out.join('\n') + '\n' : '')
